/* Shared rooms use authenticated RPCs; polling never replaces unsaved form text. */
window.AssemblyRooms=(()=>{
 let client=null,room=null,timer=null,latest=null,dirty=false,request=0;
 const names={k:'Kitala',n:'Nordland',m:'Meridia',p:'Pelagia',Chair:'Professor / Chair'};
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const modal=document.createElement('dialog');modal.className='live-room-dialog';modal.setAttribute('aria-label','Shared classroom negotiation');document.body.append(modal);
 const button=(label,action,value='',cls='secondary')=>`<button class="${cls}" data-live="${action}" data-value="${esc(value)}">${esc(label)}</button>`;
 function stop(){clearInterval(timer);timer=null;request++;}
 function close(){if(dirty&&!confirm('Close this view? Unsent text will be discarded; sent work stays in the room.'))return;stop();modal.close();}
 modal.addEventListener('cancel',e=>{e.preventDefault();close()});
 async function rpc(name,args={}){const {data,error}=await client.rpc(name,args);if(error)throw error;return data;}
 function error(e){const el=modal.querySelector('#roomStatus');if(el){el.textContent=e.code==='PGRST202'||e.code==='42883'?'Live classrooms need the live-rooms.sql database update. Your existing solo simulation still works.':e.message||'Connection failed. Your unsent text remains here. Retry when online.';el.className='account-status error';}}
 function shell(html){modal.innerHTML=button('Close','close')+'<span class="eyebrow">ASSEMBLY / LIVE CLASSROOM</span>'+html+'<p id="roomStatus" class="account-status" role="status"></p>';}
 async function open(){stop();room=null;latest=null;dirty=false;client=AssemblyAccount.connection();shell('<h2>Shared negotiations</h2><p>Loading your classrooms...</p>');if(!modal.open)modal.showModal();try{if(!client)throw Error('Sign in first.');await list()}catch(e){error(e)}}
 async function list(){stop();room=null;latest=null;dirty=false;const rooms=await rpc('assembly_live_list'),{data:classes,error:err}=await client.from('assembly_classes').select('id,title,teacher_id');if(err)throw err;const {data:user,error:authError}=await client.auth.getUser();if(authError)throw authError;const own=(classes||[]).filter(c=>c.teacher_id===user.user?.id);shell('<h2>Join your classroom negotiation</h2><p>Each student uses their own device and claims a different delegation. Your professor facilitates as Chair. Rooms support 2–4 student delegates plus the professor; larger classes can use multiple rooms.</p><p class="note">Messages, drafts and positions are shared with everyone seated in the room and your professor. Classroom membership alone does not reserve a delegation.</p>'+(own.length?'<form id="roomCreate"><label class="plan-field">Classroom<select name="classId">'+own.map(c=>'<option value="'+esc(c.id)+'">'+esc(c.title)+'</option>').join('')+'</select></label><label class="plan-field">Negotiation title<input name="title" maxlength="100" required placeholder="Equitable access - group 1"></label><button class="primary">Create negotiation room</button></form>':'')+(rooms.length?rooms.map(r=>'<article class="account-card"><h3>'+esc(r.title)+'</h3><p>'+esc(r.phase)+' / '+r.seats+' of 4 delegation seats</p>'+button('Open room','room',r.id)+'</article>').join(''):'<p>No rooms yet. Ask your professor to create one for this classroom.</p>')+button('Refresh rooms','list'));}
 async function enter(id){stop();dirty=false;room=await rpc('assembly_live_snapshot',{target_room:id});latest=room;render();timer=setInterval(poll,4000);}
 async function poll(){if(!room||!modal.open)return;const ticket=++request;try{const update=await rpc('assembly_live_snapshot',{target_room:room.id});if(ticket!==request||!modal.open)return;latest=update;const el=modal.querySelector('#roomSync');if(update.revision!==room.revision){el.textContent='New activity is available. Load updates when ready; unsent text will be kept.';el.hidden=false;}else if(el)el.textContent='Connected. Checking for updates every 4 seconds.';}catch(e){if(ticket===request)error(e)}}
 function fields(){return Object.fromEntries([...modal.querySelectorAll('textarea')].map(el=>[el.id,el.value]));}
 function render(saved={}){const r=room,canRead=r.teacher||r.role,closed=r.phase==='adopted';
  shell('<h2>'+esc(r.title)+'</h2><div class="room-phase"><b>'+esc(r.phase.toUpperCase())+'</b><span>Draft '+r.draft_version+' / '+esc(r.teacher?'Professor / Chair':names[r.role]||'Choose a seat')+'</span></div><p id="roomSync" role="status">Connected. Checking for updates every 4 seconds.</p>'+button('Load updates','refresh')+button('All rooms','list')+'<div class="room-seats">'+Object.entries(names).filter(([k])=>k!=='Chair').map(([id,name])=>'<article><b>'+name+'</b><p>'+ (r.seats.includes(id)?'Seat occupied':'Available')+'</p>'+(!r.teacher&&!r.role&&r.phase==='lobby'&&!r.seats.includes(id)?button('Take this role','join',id):'')+(r.teacher&&r.phase==='lobby'&&r.seats.includes(id)?button('Release seat','release',id):'')+'</article>').join('')+'</div>'+(canRead?'<details><summary>Your briefing and procedure</summary><p>'+(r.teacher?'Give delegates equal opportunities to contribute. Move from informal consultation to committee consideration, then closing plenary. Return to consultation if an objection remains.':esc(Roles.get(r.role)?.priority||''))+'</p><p>Live rooms negotiate policy wording freely. The solo exercise’s numerical thresholds are background prompts, not enforced conditions here. Only occupied seats participate; absent countries are not AI or scripted voters.</p><p>Review the common text, discuss changes, and explicitly record your position at committee and again in plenary. An explanation can accompany no objection. An objection blocks the consensus pathway.</p><p>Student browser sessions are device-specific. If a student loses their sign-in, the professor can release their seat only before consultation starts.</p></details><h3>Shared resolution</h3><p>One shared draft. During consultation, any seated delegate can circulate revised wording. Record the reason in discussion; previous versions remain in the record.</p><textarea id="roomDraft" maxlength="6000" '+(r.phase!=='consultation'?'readonly':'')+'>'+esc(r.draft)+'</textarea>'+(r.phase==='consultation'?button('Circulate revised wording','draft','','primary'):'')+(!r.teacher&&['committee','plenary'].includes(r.phase)?'<h3>Your position</h3><label class="reflection-field">Explanation (optional)<textarea id="roomExplanation" maxlength="600"></textarea></label>'+button('No objection to adoption','respond','no_objection','primary')+button('Object / further consultation needed','respond','object'):'')+'<h3>Recorded positions</h3>'+r.seats.map(id=>'<p><b>'+names[id]+':</b> '+esc(r.responses[id]?.position?.replace('_',' ')||'Awaiting response')+(r.responses[id]?.explanation?' - '+esc(r.responses[id].explanation):'')+'</p>').join('')+(r.teacher&&!closed?'<div class="room-chair"><h3>Chair controls</h3>'+button({lobby:'Open informal consultation',consultation:'Submit to Committee A',committee:'Send recommendation to plenary',plenary:'Confirm final adoption'}[r.phase],'advance','','primary')+(['committee','plenary'].includes(r.phase)?button('Return to consultation','reopen'):'')+'</div>':'')+'<h3>Discussion and record</h3>'+(!closed?'<label class="reflection-field">Statement, question, offer or response<textarea id="roomMessage" maxlength="1000" placeholder="State your position and explain your reasoning..."></textarea></label>'+button('Send to this room','message','','primary'):'<p class="note">Adopted. This shared text and participation record are now read-only.</p>'+button('Download final agreement (PDF)','download','','primary'))+'<div class="room-log">'+(r.events.length?r.events.slice().reverse().map(e=>'<article><b>'+esc(names[e.actor]||e.actor)+' / '+esc(e.kind)+' / '+esc(e.phase)+'</b><p>'+esc(e.text)+'</p><small>'+esc(e.at)+'</small></article>').join(''):'<p>No discussion yet.</p>')+'</div>':'<p>Take an available delegation seat to see the draft and participate. If consultation has started, ask your professor to create another room.</p>'));
  if(saved.roomDraft&&saved.roomDraft!==r.draft&&r.phase==='consultation'){const warning=document.createElement('section');warning.className='note';warning.innerHTML='<b>Your unsent draft was retained.</b><p>Compare it with the current shared draft before circulating. Saving will replace the shared wording.</p><details><summary>Current shared wording</summary><p class="contribution-text">'+esc(r.draft)+'</p></details><label><input type="checkbox" id="roomCompared"> I reviewed the current shared draft.</label>';modal.querySelector('#roomDraft').before(warning);}
  for(const [id,value] of Object.entries(saved)){const el=modal.querySelector('#'+id);if(el&&!el.readOnly)el.value=value;}
 }
 async function action(kind,payload){const id=room.id;request++;const updated=await rpc('assembly_live_action',{target_room:id,action_name:kind,payload});if(!modal.open||room?.id!==id)return;room=latest=updated;render();dirty=false;}
 function download(){if(room.phase!=='adopted')return;const r={live:true,title:room.title,id:'ROOM-'+room.id.slice(0,8),date:new Date().toISOString(),mode:'live',roster:room.seats.map(id=>names[id]).join('; ')+'; Professor / Chair',rows:[],sections:[{title:'Decision',text:'Adopted without objection by all occupied student delegation seats after separate Committee A and closing-plenary consideration. Independent fictional educational exercise; not an official WHO agreement.'},{title:'Adopted resolution - version '+room.draft_version,text:room.draft},{title:'Final explanations of position',text:room.seats.map(id=>names[id]+': '+room.responses[id].position+'; '+(room.responses[id].explanation||'No explanation recorded.')).join('\n')},{title:'Shared participation and draft record',text:room.events.map(e=>(names[e.actor]||e.actor)+' / '+e.kind+' / '+e.phase+' / '+e.at+': '+e.text).join('\n')},{title:'Scope',text:'Human participants on separate devices. No AI delegates. Only occupied seats participate. Policy wording is not automatically converted into resource allocations or implementation outcomes. Messages and drafts were shared with room participants and the classroom professor.'}]};const url=URL.createObjectURL(new Blob([Agreement.pdf(r)],{type:'application/pdf'}));const a=document.createElement('a');a.href=url;a.download=r.id+'-agreement.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 modal.addEventListener('input',()=>{dirty=true});
 modal.addEventListener('click',async e=>{const b=e.target.closest('[data-live]');if(!b)return;const kind=b.dataset.live,value=b.dataset.value;b.disabled=true;try{
  if(kind==='close'){close();return}if(kind==='list'){if(dirty&&!confirm('Leave this room view? Unsent text will be discarded.'))return;await list();return}if(kind==='room'){await enter(value);return}if(kind==='download'){download();return}
  if(kind==='refresh'){const saved=fields(),prior=room.draft;const updated=await rpc('assembly_live_snapshot',{target_room:room.id});room=latest=updated;if(saved.roomDraft===prior)delete saved.roomDraft;render(saved);return}
  if(kind==='join')await action('join',{role:value});
  if(kind==='release'){if(confirm('Release this delegation seat before the session starts?'))await action('release',{role:value})}
  if(kind==='message'){const saved=fields();await action('message',{text:saved.roomMessage});delete saved.roomMessage;render(saved);dirty=Boolean(saved.roomDraft&&saved.roomDraft!==room.draft||saved.roomExplanation)}
  if(kind==='draft'){if(modal.querySelector('#roomCompared')&&!modal.querySelector('#roomCompared').checked)throw Error('Review the current shared wording and tick the confirmation before circulating.');await action('draft',{text:modal.querySelector('#roomDraft').value,revision:room.revision});}
  if(kind==='respond')await action('respond',{position:value,explanation:modal.querySelector('#roomExplanation').value,phase:room.phase,draft_version:room.draft_version});
  if(kind==='advance')await action('advance',{revision:room.revision});if(kind==='reopen')await action('reopen',{});
 }catch(err){error(err)}finally{b.disabled=false}});
 modal.addEventListener('submit',async e=>{e.preventDefault();if(e.target.id!=='roomCreate')return;const b=e.target.querySelector('button');b.disabled=true;try{const id=await rpc('assembly_live_create',{target_class:e.target.elements.classId.value,room_title:e.target.elements.title.value});await enter(id)}catch(err){error(err)}finally{b.disabled=false}});
 return {open};
})();
